import 'package:flutter/material.dart';import '../services/api.dart';import '../services/ad_service.dart';import '../widgets/ad_banner.dart';
class HomeScreen extends StatefulWidget{const HomeScreen({super.key});State<HomeScreen> createState()=>_Home();}
class _Home extends State<HomeScreen>{final ad=AdService();List cats=[];bool loading=true;void initState(){super.initState();ad.loadInterstitial();load();}Future<void> load()async{try{cats=await Api.get('/categories');}finally{if(mounted)setState(()=>loading=false);}}Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text("طلبات V1"),actions:[IconButton(onPressed:()=>ad.showInterstitial(),icon:const Icon(Icons.local_offer))]),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(16),children:[const Text("اختار القسم",style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:12),const AdBanner(),const SizedBox(height:12),...cats.map((cat)=>Card(child:ExpansionTile(title:Text(cat["name"]),children:[...(cat["products"] as List).map((p)=>ListTile(title:Text(p["name"]),subtitle:Text("${p["price"]} جنيه"),trailing:IconButton(icon:const Icon(Icons.add_shopping_cart),onPressed:()=>ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text("أضيفت للسلة")))))])))])));}}
